'use strict';
const twinState={mode:'workflow',choice:'RV-1048',angle:-28,zoom:1,time:480,playing:false,settings:{...TwinSimulation.defaults},result:null};
const twinPositions=[[90,110],[340,110],[600,110],[600,340],[340,340],[90,340]],twinColors=['#068667','#2682a0','#4568ab','#9266aa','#068667','#2682a0'];
const twinOriginalRender=render;
function cube(cls,x,y,w,d,h,color,label=''){return `<div class="twin-cube ${cls}" style="--x:${x}px;--y:${y}px;--w:${w}px;--d:${d}px;--h:${h}px;--color:${color}"><i class="face front"></i><i class="face side"></i><i class="face top"></i>${label}</div>`;}
function twinLocation(r){return openIssues(r).length?6:r.stage===4?5:[0,1,3,4][r.stage];}
function twinShell(){return `<div class="twin-heading"><div><h1>Warehouse Twin</h1><p>Explore the flow. Test the change.</p></div><span class="tag amber">Digital twin concept · Simulated data</span></div><div class="twin-mode" role="group" aria-label="Twin mode"><button data-twin-mode="workflow" aria-pressed="${twinState.mode==='workflow'}">Current sample workflow</button><button data-twin-mode="scenario" aria-pressed="${twinState.mode==='scenario'}">What-if simulation</button></div><div class="twin-layout"><section class="twin-view"><div class="twin-tools"><div><strong id="twin-scene-label"></strong><small>Illustrative layout · not an HPE floor plan</small></div><div><button id="twin-left" aria-label="Rotate warehouse left">↶</button><button id="twin-right" aria-label="Rotate warehouse right">↷</button><button id="twin-zoom" aria-label="Change warehouse zoom">Zoom</button><button id="twin-reset-view">Reset view</button></div></div><div class="twin-viewport" aria-label="Interactive 3D warehouse"><div class="twin-world" id="twin-world"><div class="twin-floor"></div><div class="twin-route"></div>${TwinSimulation.stations.map((s,i)=>{const [x,y]=twinPositions[i];return cube('station',x,y,160,100,30,twinColors[i],`<button class="station-label" data-station="${i}">${s}<small id="station-count-${i}"></small></button>`)+[0,1].map(j=>cube('rack',x+j*65+15,y+15,45,30,65,'#74818b')).join('');}).join('')}${cube('hold',690,410,130,100,12,'#c95043','<span class="station-label">Exception hold</span>')}<div id="twin-items"></div></div></div><div class="twin-legend"><span><i style="background:#068667"></i>Ready / processing</span><span><i style="background:#ba780c"></i>Queued</span><span><i style="background:#c33e38"></i>Exception hold</span></div><div class="twin-playback" id="twin-playback" hidden><button id="twin-play">Play shift</button><label>Shift time <input type="range" id="twin-time" min="0" max="480" step="5" value="480"></label><output id="twin-clock">8h 00m</output></div><div class="twin-records" id="twin-records"></div></section><aside class="twin-sidebar" id="twin-sidebar"></aside></div><section id="twin-comparison"></section><details class="twin-assumptions"><summary>Model assumptions and limits</summary><p>This concept uses a simplified route: receiving → inspection → testing → disposition → inventory → shipping. All simulated items follow this route. Teardown, DEKIT, repair/recycling branches, shifts, breaks, skill constraints and equipment failures are not yet modeled. The 3D positions are illustrative.</p><p>Default receiving time is 9 minutes; other times and capacities are demonstration assumptions, not validated assessment findings. Arrivals are spread across an eight-hour shift; service times vary ±20%. Exceptions delay entry to receiving. Workers are dedicated to each station; changing staff changes every non-testing station. Testing has a separate capacity control.</p><p>Comparisons average 20 paired seeded runs. Completed means shipped within eight hours. Turnaround for completed items can be biased toward faster items; the all-arrivals measure includes processing after the shift. Ranges show variation between runs, not a statistical confidence interval. Playback shows one run and can differ from the averages.</p></details>`;}
function twinView(){return twinShell();}
render=function(){if((location.hash.slice(1)||'overview')!=='twin'){twinOriginalRender();return;}page='twin';$('#main').innerHTML=twinView();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page==='twin'));$('#page-label').textContent='Warehouse Twin';$('#exception-count').textContent=allIssues().length;bindTwin();};
function bindTwin(){document.querySelectorAll('[data-twin-mode]').forEach(b=>b.onclick=()=>{twinState.playing=false;twinState.mode=b.dataset.twinMode;render();});$('#twin-left').onclick=()=>{twinState.angle-=15;positionTwin();};$('#twin-right').onclick=()=>{twinState.angle+=15;positionTwin();};$('#twin-zoom').onclick=()=>{twinState.zoom=twinState.zoom===1?1.25:1;positionTwin();};$('#twin-reset-view').onclick=()=>{twinState.angle=-28;twinState.zoom=1;positionTwin();};document.querySelectorAll('[data-station]').forEach(b=>b.onclick=()=>showStation(+b.dataset.station));$('#twin-time').oninput=e=>{twinState.time=+e.target.value;twinState.playing=false;updateTwinScene();};$('#twin-play').onclick=()=>{twinState.playing=!twinState.playing;if(twinState.playing&&twinState.time>=480)twinState.time=0;$('#twin-play').textContent=twinState.playing?'Pause':'Play shift';};positionTwin();if(twinState.mode==='scenario')showScenario();else showTraveler();updateTwinScene();}
function positionTwin(){const v=$('.twin-viewport');if(!v)return;const scale=Math.min(v.clientWidth/1000,0.85)*twinState.zoom;$('#twin-world').style.transform=`translate(-50%,-50%) scale(${scale}) rotateX(52deg) rotateZ(${twinState.angle}deg)`;}
window.addEventListener('resize',positionTwin);
function updateTwinScene(){if(page!=='twin')return;const sim=twinState.mode==='scenario';$('#twin-scene-label').textContent=sim?'Scenario · one simulated shift':'Current sample returns';$('#twin-playback').hidden=!sim;let tokens=[],counts=Array(7).fill(0),processing=Array(7).fill(0);
 if(sim){if(!twinState.result)twinState.result=TwinSimulation.compare(twinState.settings);const run=twinState.result.example,t=twinState.time;$('#twin-time').value=t;$('#twin-clock').textContent=Math.floor(t/60)+'h '+String(t%60).padStart(2,'0')+'m';for(const r of run.items){if(r.arrival>t||r.finished<=t)continue;let s=6,state='blocked';if(!(r.hold&&r.arrival+twinState.settings.holdTime>t)){const v=r.trace.find(v=>v.end>t);if(!v)continue;s=v.stage;state=v.start>t?'queued':'processing';}const n=counts[s]++;if(state==='processing')processing[s]++;tokens.push({id:r.id,s,n,state});}$('#twin-records').innerHTML='<p>Simulated items are scenario copies. Playback never changes travelers.</p>';}
 else{for(const r of records){if(r.stage===4)continue;const s=twinLocation(r),n=counts[s]++;tokens.push({id:r.id,s,n,state:s===6?'blocked':'processing'});}$('#twin-records').innerHTML=records.filter(r=>r.stage<4).map(r=>`<button data-twin-return="${esc(r.id)}" class="${r.id===twinState.choice?'selected':''}">${esc(r.id)} <small>${openIssues(r).length?'On hold':STAGES[r.stage]}</small></button>`).join('');document.querySelectorAll('[data-twin-return]').forEach(b=>b.onclick=()=>{twinState.choice=b.dataset.twinReturn;showTraveler();updateTwinScene();});}
 window.TwinSceneData={tokens,selected:twinState.choice};window.dispatchEvent(new Event('twin-scene-update'));
 $('#twin-items').innerHTML=tokens.map(r=>{const [x,y]=r.s===6?[690,410]:twinPositions[r.s];return cube('pallet '+r.state+(r.id===twinState.choice?' chosen':''),x+12+(r.n%5)*24,y+65+Math.floor(r.n/5)*23,19,18,23,r.state==='blocked'?'#c33e38':r.state==='queued'?'#ba780c':'#068667',`<button class="pallet-hit" aria-label="${r.id}, ${r.state}" data-pallet="${r.id}"><span>${r.id}</span></button>`);}).join('');document.querySelectorAll('[data-pallet]').forEach(b=>b.onclick=()=>{if(sim){const r=twinState.result.example.items.find(r=>r.id===b.dataset.pallet);$('#twin-sidebar').innerHTML=`<h2>${esc(r.id)}</h2><p>Scenario item · no operational traveler</p><p>Arrival: ${r.arrival.toFixed(0)} min<br>Exception hold: ${r.hold?'Yes':'No'}<br>Completion: ${r.finished.toFixed(0)} min</p><button class="secondary" id="back-scenario">Back to variables</button>`;$('#back-scenario').onclick=showScenario;}else{twinState.choice=b.dataset.pallet;showTraveler();updateTwinScene();}});TwinSimulation.stations.forEach((_,i)=>{$('#station-count-'+i).textContent=counts[i]+' present'+(sim?' · '+processing[i]+' processing':'');});}
function showTraveler(){const r=records.find(r=>r.id===twinState.choice)||records[0];twinState.choice=r.id;const issues=openIssues(r);$('#twin-sidebar').innerHTML=`<span class="tag">Digital Traveler</span><h2>${esc(r.id)}</h2><p>${esc(r.product)}</p>${statusTag(r)}<dl><dt>Location</dt><dd>${issues.length?'Exception hold':STAGES[r.stage]}</dd><dt>Owner</dt><dd>${esc(r.owner)}</dd><dt>Next step</dt><dd>${issues.length?'Resolve open exception':r.stage===4?'Closed':STAGES[r.stage+1]}</dd></dl>${issues.map(e=>`<div class="twin-issue"><strong>${esc(e.title)}</strong><p>${esc(e.owner)} · ${esc(e.severity)} priority</p></div>`).join('')}<button class="primary" data-open="${esc(r.id)}" data-tab="${issues.length?'exceptions':'details'}">${issues.length?'Review exception':'Open traveler'}</button><div class="twin-explanation"><h3>What is happening?</h3><p>${issues.length?'This return stays on hold until its owner records a resolution note.':'This item is eligible for review at its current workflow stage.'}</p><small>Rule-based explanation of current browser records. No AI model call.</small></div><p class="twin-fine">Testing positions are modeled in simulation only. The current prototype does not record station-level testing events.</p>`;$('#twin-comparison').innerHTML='';}
const twinControls=[['volume','Returns per shift',10,120,5,'items'],['staff','Staff at each non-testing station',1,5,1,'people'],['testCapacity','Testing positions',1,6,1,'positions'],['testTime','Testing time',5,90,5,'min'],['exceptionRate','Returns with exceptions',0,80,5,'%'],['holdTime','Exception resolution delay',0,480,30,'min']];
function showScenario(){if(!twinState.result)twinState.result=TwinSimulation.compare(twinState.settings);$('#twin-sidebar').innerHTML=`<h2>Change the conditions</h2><p>Compare with a fixed baseline. Changes apply only after you run the scenario.</p><label class="twin-preset">Start with a scenario<select id="twin-preset"><option value="custom">Custom variables</option><option value="surge">Demand surge · +50%</option><option value="testing">Testing capacity · half</option><option value="exceptions">Resolve exceptions faster</option></select></label>${twinControls.map(([k,label,min,max,step,unit])=>`<label class="twin-variable" for="var-${k}"><span>${label}<output id="value-${k}">${twinState.settings[k]} ${unit}</output></span><input id="var-${k}" type="range" min="${min}" max="${max}" step="${step}" value="${twinState.settings[k]}"></label>`).join('')}<button class="primary" id="twin-run">Run scenario</button><button class="secondary" id="twin-baseline">Reset to baseline</button><p id="twin-pending" role="status"></p><small>Eight-hour shift · 20 paired runs · Demonstration assumptions</small>`;twinControls.forEach(([k,,,,,unit])=>{$('#var-'+k).oninput=e=>{$('#value-'+k).textContent=e.target.value+' '+unit;$('#twin-pending').textContent='Variables changed. Run scenario to update the comparison.';};});$('#twin-run').onclick=()=>{twinControls.forEach(([k])=>twinState.settings[k]=+$('#var-'+k).value);twinState.result=TwinSimulation.compare(twinState.settings);twinState.time=480;twinState.playing=false;$('#twin-pending').textContent='Scenario calculated. Results are shown below the warehouse.';renderComparison();updateTwinScene();};$('#twin-baseline').onclick=()=>{twinState.settings={...TwinSimulation.defaults};twinState.result=null;showScenario();updateTwinScene();};$('#twin-preset').onchange=e=>{const p={...TwinSimulation.defaults};if(e.target.value==='surge')p.volume=60;if(e.target.value==='testing')p.testCapacity=1;if(e.target.value==='exceptions')p.holdTime=30;twinControls.forEach(([k,,,,,u])=>{$('#var-'+k).value=p[k];$('#value-'+k).textContent=p[k]+' '+u;});$('#twin-pending').textContent='Preset loaded. Run scenario to compare.';};renderComparison();}
function renderComparison(){const {baseline:b,scenario:s,example:r}=twinState.result;const changed=twinControls.filter(([k])=>twinState.settings[k]!==TwinSimulation.defaults[k]);$('#twin-comparison').innerHTML=`<div class="twin-results"><h2>Impact of your scenario</h2><p>${changed.length?changed.map(([k,l])=>esc(l)+': '+TwinSimulation.defaults[k]+' → '+twinState.settings[k]).join(' · '):'Baseline settings unchanged. Both runs use the same inputs.'}</p><div class="table-wrap"><table><thead><tr><th>Measure</th><th>Baseline</th><th>Scenario</th><th>Change</th></tr></thead><tbody>${[['Completed within shift','completed','items'],['Work remaining at shift end','wip','items'],['Turnaround · completed items','turnaround','min'],['Turnaround · all arrivals, including overtime','eventualTurnaround','min']].map(([label,k,u])=>`<tr><td>${label}</td><td>${b[k].toFixed(1)} ${u}</td><td>${s[k].toFixed(1)} ${u}</td><td>${s[k]-b[k]>0?'+':''}${(s[k]-b[k]).toFixed(1)} ${u}</td></tr>`).join('')}</tbody></table></div><div class="twin-result-note"><strong>Read the tradeoff</strong><p>${s.completed.toFixed(1)} items complete within the shift versus ${b.completed.toFixed(1)} in the baseline. The largest average station wait in the displayed run is at ${esc(r.bottleneck)}. Scenario completions range from ${s.minCompleted} to ${s.maxCompleted} across 20 runs.</p><p>Adding capacity at one station can move congestion elsewhere. Compare all-arrivals turnaround and unfinished work alongside completed throughput.</p></div><div class="twin-bars">${r.detail.map(d=>`<div><span>${d.name}</span><meter min="0" max="1" value="${d.utilization}">${Math.round(d.utilization*100)}%</meter><small>${Math.round(d.utilization*100)}% busy · ${d.wait.toFixed(0)} min mean wait</small></div>`).join('')}</div></div>`;}
function showStation(i){if(twinState.mode==='scenario'){const d=twinState.result.example.detail[i];$('#twin-sidebar').innerHTML=`<h2>${esc(d.name)}</h2><p>One displayed simulation run at shift end</p><dl><dt>Waiting at shift end</dt><dd>${d.queue}</dd><dt>Processing</dt><dd>${d.processing}</dd><dt>Utilization</dt><dd>${Math.round(d.utilization*100)}%</dd><dt>Average wait, including overtime</dt><dd>${d.wait.toFixed(1)} min</dd></dl><button id="back-scenario" class="secondary">Back to variables</button>`;$('#back-scenario').onclick=showScenario;}else{const rows=records.filter(r=>r.stage<4&&twinLocation(r)===i);$('#twin-sidebar').innerHTML=`<h2>${TwinSimulation.stations[i]}</h2><p>${rows.length} current sample returns</p>${rows.map(r=>`<button class="secondary" data-open="${esc(r.id)}">${esc(r.id)} · Open traveler</button>`).join('')||'<p>No sample returns mapped here. Station-level activity is illustrated in simulation mode.</p>'}`;}}
const twinNav=document.createElement('a');twinNav.href='#twin';twinNav.dataset.page='twin';twinNav.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2 10 5v10l-10 5L2 17V7zm0 10v10M2 7l10 5 10-5"/></svg><span>Warehouse Twin</span>';document.querySelector('nav').append(twinNav);
const twinOriginalSave=save;save=function(){twinOriginalSave();window.dispatchEvent(new Event('twin-record-change'));};window.addEventListener('twin-record-change',()=>{if(page==='twin'&&twinState.mode==='workflow'){showTraveler();updateTwinScene();}});
setInterval(()=>{if(page==='twin'&&twinState.mode==='scenario'&&twinState.playing){twinState.time=Math.min(480,twinState.time+5);updateTwinScene();if(twinState.time===480){twinState.playing=false;$('#twin-play').textContent='Replay shift';}}},150);
render();
